<script setup lang="ts">
import { computed } from "vue"; import { useI18n } from "vue-i18n"; import TodoCard from "./TodoCard.vue"; import type { TodoCardRow } from "./todoFilter";
const props = defineProps<{ id: string; labelKey: string; dot: string; todos: TodoCardRow[]; draggingId: string | null; over: boolean; doneLimit?: number }>();
const emit = defineEmits<{ add: []; dragstart: [TodoCardRow, DragEvent]; dragend: []; dragover: [DragEvent]; dragleave: [DragEvent]; drop: []; move: [TodoCardRow, string]; open: [TodoCardRow]; remove: [TodoCardRow]; openSpec: [string]; more: [] }>();
const { t } = useI18n(); const shown = computed(() => props.id === "done" ? props.todos.slice(0, props.doneLimit ?? 50) : props.todos);
</script>
<template><section class="tw-col" :class="{ over }" @dragover="emit('dragover', $event)" @dragleave="emit('dragleave', $event)" @drop.prevent="emit('drop')"><div class="tw-col-head"><span class="tw-col-dot" :style="{background: dot}"></span><span class="tw-col-name">{{ t(labelKey) }}</span><span class="tw-col-count">{{ todos.length }}</span><button class="tw-col-add" @click="emit('add')">+</button></div><div class="tw-col-body scroll"><div v-if="!shown.length" class="tw-col-empty">{{ over ? t('todoDropHere') : t('todoColEmpty') }}</div><TodoCard v-for="todo in shown" :key="todo.id" :todo="todo" :dragging="draggingId === todo.id" :color="dot" @dragstart="emit('dragstart', todo, $event)" @dragend="emit('dragend')" @move="emit('move', todo, $event)" @open="emit('open', todo)" @remove="emit('remove', todo)" @open-spec="emit('openSpec', $event)" /><button v-if="id === 'done' && shown.length < todos.length" class="tw-more" @click="emit('more')">{{ t('todoMore') }}</button></div></section></template>
